import java.util.*;

public class Main {
    void merge(int[] nums1, int m, int[] nums2, int n) {
        int i = m - 1, j = n - 1, k = m + n - 1;                     // last real element of each, and the last slot
        while (j >= 0) {
            if (i >= 0 && nums1[i] > nums2[j]) {
                nums1[k] = nums1[i];                                       // nums1's candidate is larger
                i--;
            } else {
                nums1[k] = nums2[j];                                         // nums2's candidate is larger or nums1 is exhausted
                j--;
            }
            k--;
        }
    }

    public static void main(String[] args) {
        int[] nums1 = {1, 2, 3, 0, 0, 0};
        Main solution = new Main();
        solution.merge(nums1, 3, new int[]{2, 5, 6}, 3);
        System.out.println(Arrays.toString(nums1));
    }
}

